# ==============================================================================
# 🚀 1-CLICK PRODUCTION DEPLOYER FOR PHAROAH ERP (#PH-REV-667)
# Steps 1, 2, 3 & 4: Master Sync Engine & File Separation Architecture
# ==============================================================================
import os
import sys
import json
import zlib
import base64
import subprocess

print("=" * 72)
print("🚀 PHAROAH ERP • MASTER DEPLOYER (#PH-REV-667)")
print("Steps 1, 2, 3, 4: Decoupled Modules, JSON Batch, LWW Guard & D1 Cloud Engine")
print("=" * 72 + "\n")

# 1. AUTO-LOCATE REPO DIRECTORY IN COLAB
repo_path = "/content/131-new-ph"
if os.path.exists(repo_path):
    os.chdir(repo_path)
    print(f"📂 Switched directory to: {repo_path}")
else:
    cwd = os.getcwd()
    print(f"📂 Working in current directory: {cwd}")

# 2. EXTRACT AND APPLY ALL SYSTEM FILES
print("\n📦 Step 1/4: Applying all decoupled modules and sync engine code...")
BUNDLE_DATA = ""

raw_bytes = zlib.decompress(base64.b64decode(BUNDLE_DATA))
files_dict = json.loads(raw_bytes.decode('utf-8'))

for rel_file, content in files_dict.items():
    os.makedirs(os.path.dirname(rel_file), exist_ok=True)
    with open(rel_file, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"  ✔ Written: {rel_file}")

print(f"\n✨ Successfully updated {len(files_dict)} production files!")

# 3. GIT ADD & COMMIT
print("\n📥 Step 2/4: Creating Git Commit for #PH-REV-667...")
subprocess.run(["git", "add", "."], check=False)
commit_msg = "🚀 #PH-REV-667: Step 1, 2, 3, 4 - Decoupled Modules & JSON Batch Master Sync Engine"
subprocess.run(["git", "commit", "-m", commit_msg], check=False)

# 4. PUSH TO GITHUB (Triggers Automatic APK Build on GitHub Actions)
print("\n📤 Step 3/4: Pushing to GitHub (origin main)...")
push_res = subprocess.run(["git", "push", "origin", "main"], capture_output=True, text=True)
if push_res.returncode == 0:
    print("✔ Pushed to GitHub successfully! APK build is now running on GitHub Actions.")
else:
    print("⚠ Git push output:\n", push_res.stderr or push_res.stdout)

# 5. BUILD FLUTTER WEB & DEPLOY TO CLOUDFLARE PAGES
print("\n🔨 Step 4/4: Building Flutter Web and Deploying to Cloudflare Pages...")
try:
    subprocess.run(["flutter", "pub", "get"], check=False)
    build_cmd = [
        "flutter", "build", "web",
        "-t", "lib/web_live_sync/web_main.dart",
        "--release",
        "--base-href", "/",
        "--pwa-strategy=none"
    ]
    subprocess.run(build_cmd, check=False)
    
    deploy_cmd = [
        "npx", "wrangler", "pages", "deploy", "build/web",
        "--project-name=pharoah-erp",
        "--commit-dirty=true"
    ]
    subprocess.run(deploy_cmd, check=False)
except Exception as e:
    print(f"⚠ Build notice: {e}")

print("\n" + "=" * 72)
print("🎉 REVISION #PH-REV-667 DEPLOYMENT COMPLETED!")
print("🔗 Live Portal URL: https://pharoah-erp.pages.dev")
print("=" * 72)
